using System.ComponentModel;
using System.Net.Http.Json;
using ModelContextProtocol.Server;

namespace McpServer;

/// <summary>
/// MCP tools are discovered by the SDK via the [McpServerToolType] attribute on the class
/// and [McpServerTool] on each method. The SDK uses DI to resolve constructor parameters.
/// </summary>
[McpServerToolType]
public class WeatherTools
{
    private readonly HttpClient _httpClient;

    // The SDK resolves this via DI — register a named/typed HttpClient in Program.cs
    public WeatherTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [McpServerTool, Description("Get current weather for a city")]
    public async Task<string> GetWeather(
        [Description("City name, e.g. 'London'")] string city,
        CancellationToken cancellationToken = default)
    {
        var response = await _httpClient.GetFromJsonAsync<WeatherResponse>(
            $"/weather?city={Uri.EscapeDataString(city)}",
            cancellationToken);

        return response is not null
            ? $"{response.City}: {response.TemperatureC}°C, {response.Condition}"
            : "Weather data not available.";
    }

    [McpServerTool, Description("Get 5-day forecast for a city")]
    public async Task<string> GetForecast(
        [Description("City name")] string city,
        [Description("Number of days (1-5)")] int days = 5,
        CancellationToken cancellationToken = default)
    {
        var response = await _httpClient.GetFromJsonAsync<ForecastDay[]>(
            $"/forecast?city={Uri.EscapeDataString(city)}&days={days}",
            cancellationToken);

        if (response is null || response.Length == 0)
            return "Forecast not available.";

        return string.Join("\n", response.Select(d =>
            $"{d.Date:yyyy-MM-dd}: {d.HighC}°C / {d.LowC}°C, {d.Condition}"));
    }
}

public record WeatherResponse(string City, double TemperatureC, string Condition);
public record ForecastDay(DateOnly Date, double HighC, double LowC, string Condition);

